    'options.heading.gpu_display' => 'Affichage',
    'options.heading.names' => 'Noms',
    'options.desc.color_theme' => "Définir le thème de couleurs.\n\nChoisir parmi tous les fichiers de thème du\nrépertoire de thèmes fourni avec candy-top et\n\"~/.config/candy-top/themes\".\n\n\"pastel\" est le thème par défaut de candy-top.\n\"Default\" pour le thème intégré de btop.\n\"TTY\" pour le thème intégré en 16 couleurs.\n\nPour les mises à jour de thèmes, voir :\nhttps://github.com/aristocratos/btop",
    'options.desc.theme_background' => "Indique si l'arrière-plan défini par le thème doit être affiché.\n\nMettre à False pour obtenir la transparence\nde l'arrière-plan du terminal.",
    'options.desc.truecolor' => "Indique si le truecolor 24 bits doit être utilisé.\n\nSi False, les couleurs 24 bits sont converties en\n256 couleurs (cube de couleurs 6x6x6).\n\nMettre à False si votre terminal ne prend pas en\ncharge le truecolor et ne peut pas convertir en\n256 couleurs.",
    'options.desc.force_tty' => "Mode TTY.\n\nMettre à true pour forcer le mode tty,\nqu'un vrai tty ait été détecté ou non.\n\nForce le mode 16 couleurs et le thème TTY,\nrègle tous les symboles de graphique sur \"tty\" et\nremplace les autres symboles non compatibles tty.",
    'options.desc.vim_keys' => "Activer les touches vim.\nMettre à True pour activer les touches \"h,j,k,l\"\ncomme contrôle directionnel dans les listes.\n\nLes touches en conflit\nh (help) et k (kill)\nrestent accessibles en maintenant Maj.",
    'options.desc.disable_mouse' => 'Désactiver tous les événements de la souris.',
    'options.desc.disable_presets' => "Désactiver les presets.\n\n\"Off\" Tous les presets sont activés.\n\n\"Default\" Le preset par défaut est désactivé.\n\n\"Custom\" Les presets personnalisés sont désactivés.\n\n\"All\" Tous les presets sont désactivés.",
    'options.desc.presets' => "Définir des presets pour la disposition des boîtes.\n\nLe preset 0 affiche toujours toutes les boîtes\navec les réglages par défaut.\n9 presets au maximum.\n\nFormat : \"box_name:P:G,box_name:P:G\"\nP=(0 ou 1) pour les positions alternatives.\nG=symbole de graphique de la boîte.\n\nLe format de la boîte proc peut aussi être \"proc:P:G:W\"\nW=(0 - 100) pour le pourcentage de largeur.\n\nUtiliser une espace \" \" comme séparateur entre\nles presets.\n\nExemple :\n\"mem:0:tty,proc:1:default:80 cpu:0:braille\"",
    'options.desc.shown_boxes' => "Définit manuellement les boîtes à afficher.\n\nLes valeurs disponibles sont \"cpu mem net proc\"\net \"ctr\" pour la boîte des conteneurs,\n\"vms\" pour le tableau de bord des VM,\n\"ipmi\" pour la boîte BMC.\nOu \"gpuN\" pour l'indice de GPU N.\nJusqu'à 6 boîtes GPU à la fois.\nSéparer les valeurs par des espaces.\n\nBasculer entre les presets avec la touche \"p\".",
    'options.desc.cpu_bottom' => "Emplacement de la boîte cpu.\n\nAfficher la boîte cpu en bas de l'écran plutôt\nqu'en haut.",
    'options.desc.mem_below_net' => "Emplacement de la boîte mem.\n\nAfficher la boîte mem sous la boîte net plutôt\nqu'au-dessus.",
    'options.desc.proc_left' => "Emplacement de la boîte proc.\n\nAfficher la boîte proc à gauche de l'écran\nplutôt qu'à droite.",
    'options.desc.proc_box_width_percent' => "Pourcentage de largeur de la boîte proc\n\nDéfinit la largeur de la boîte proc en pourcentage\nlorsque les boîtes mem ou net sont affichées.\n\nUne valeur supérieure ou inférieure à la largeur\nmaximale ou minimale pour la taille de la fenêtre\nfixera la largeur à la plus grande ou la plus\npetite possible.\n\nAjuster en direct avec Maj / Alt+Maj +\nGauche / Droite.",
    'options.desc.update_ms' => "Intervalle de mise à jour en millisecondes.\n\n2000 ms ou plus recommandé pour de meilleurs\néchantillonnages dans les graphiques.\n\nAu plancher de 100 ms, l'interface a mesuré\n45-63 ms de CPU par image (~45-50 % d'un\ncœur) : surveillez le coût.\n\nValeur min. : 100 ms\nValeur max. : 86400000 ms = 24 heures.",
    'options.desc.rounded_corners' => "Coins arrondis sur les boîtes.\n\nTrue ou False\n\nToujours False si le mode TTY est activé.",
    'options.desc.terminal_sync' => "Synchronisation de la sortie.\n\nUtiliser les séquences de sortie synchronisée du\nterminal pour réduire le scintillement sur les\nterminaux compatibles.\n\nTrue ou False.",
    'options.desc.graph_symbol' => "Symboles par défaut pour créer les graphiques.\n\n\"braille\", \"block\", \"block2\" ou \"tty\".\n\n\"braille\" offre la plus haute résolution mais\npeut manquer dans certaines polices.\n\n\"block\" a la moitié de la résolution de braille\nmais utilise des caractères plus courants.\n\n\"block2\" utilise des blocs sextants.\n\n\"tty\" n'utilise que 3 symboles différents mais\nfonctionne avec la plupart des polices.\n\nNote : \"tty\" n'a que la moitié de la résolution\nhorizontale des deux autres et affiche donc\nun historique plus court.",
    'options.desc.graph_symbol_cpu' => 'Symbole de graphique pour la boîte cpu.',
    'options.desc.graph_symbol_mem' => 'Symbole de graphique pour la boîte mem.',
    'options.desc.graph_symbol_net' => 'Symbole de graphique pour la boîte net.',
    'options.desc.graph_symbol_proc' => 'Symbole de graphique pour la boîte proc.',
    'options.desc.graph_symbol_gpu' => 'Symbole de graphique pour la boîte gpu.',
    'options.desc.clock_format' => "Dessine une horloge en haut de l'écran.\n(Visible uniquement si la boîte cpu est activée !)\n\nFormat selon strftime, chaîne vide pour\ndésactiver.\n\nOptions de format personnalisées :\n\"/host\" = nom d'hôte\n\"/user\" = nom d'utilisateur\n\"/uptime\" = durée de fonctionnement du système\n\nExemples de formats strftime :\n\"%X\" = HH:MM:SS selon la locale\n\"%H\" = heure 24h, \"%I\" = heure 12h\n\"%M\" = minute, \"%S\" = seconde\n\"%d\" = jour, \"%m\" = mois, \"%y\" = année",
    'options.desc.base_10_sizes' => "Utiliser la base 10 pour les tailles en bits et octets.\n\nUtilise KB = 1000 au lieu de KiB = 1024,\nMB = 1000KB au lieu de MiB = 1024KiB,\net ainsi de suite.\n\nTrue ou False.",
    'options.desc.background_update' => "Mettre à jour l'interface principale lorsque des menus sont affichés.\n\nTrue ou False.\n\nMettre à false si les menus scintillent trop\npour un usage confortable.",
    'options.desc.show_battery' => "Afficher les statistiques de la batterie.\n(Visible uniquement si la boîte cpu est activée !)\n\nAfficher les statistiques de la batterie dans le coin\nsupérieur droit si une batterie est présente.",
    'options.desc.selected_battery' => "Sélectionner la batterie.\n\nBatterie à utiliser si plusieurs sont présentes.\nPeut être une batterie ou un onduleur.\n\n\"Auto\" pour la détection automatique.",
    'options.desc.show_battery_watts' => "Afficher la puissance de la batterie.\n\nAfficher la puissance de décharge en décharge.\nAfficher la puissance de charge en charge.",
    'options.desc.log_level' => "Définit le niveau de journalisation\n\n\"DISABLED\", \"ERROR\", \"WARNING\",\n\"INFO\" et \"DEBUG\".\n\nLe niveau défini inclut tous les niveaux inférieurs,\nc.-à-d. \"DEBUG\" affichera toutes les informations\nde journalisation.",
    'options.desc.save_config_on_exit' => "Enregistrer la configuration à la sortie.\n\nEnregistrer automatiquement les réglages actuels\ndans le fichier de configuration à la sortie.\n\nLorsque ce réglage passe de True à False,\nun enregistrement est déclenché immédiatement.\nOn peut ainsi enregistrer manuellement en\ndésactivant puis réactivant ce réglage.",
    'options.desc.cpu_graph_upper' => "Graphique CPU supérieur.\n\nDéfinit la statistique CPU/GPU affichée dans la\nmoitié supérieure du graphique CPU.\n\nCPU :\n\"total\" = Usage cpu total. (Auto)\n\"user\" = Usage cpu en mode utilisateur.\n\"system\" = Usage cpu en mode noyau.\n+ d'autres selon le noyau.\n\nGPU :\n\"gpu-totals\" = Usage GPU par périphérique.\n\"gpu-vram-totals\" = Usage VRAM par GPU.\n\"gpu-pwr-totals\" = Consommation par GPU.\n\"gpu-average\" = Usage moyen de tous les GPU.\n\"gpu-vram-total\" = Usage VRAM de tous les GPU.\n\"gpu-pwr-total\" = Consommation de tous les GPU.\nToutes les statistiques ne sont pas prises en charge par tous les périphériques.",
    'options.desc.cpu_graph_lower' => "Graphique CPU inférieur.\n\nDéfinit la statistique CPU/GPU affichée dans la\nmoitié inférieure du graphique CPU.\n\nCPU :\n\"total\" = Usage cpu total.\n\"user\" = Usage cpu en mode utilisateur.\n\"system\" = Usage cpu en mode noyau.\n+ d'autres selon le noyau.\n\nGPU :\n\"gpu-totals\" = Usage GPU par périphérique. (Auto)\n\"gpu-vram-totals\" = Usage VRAM par GPU.\n\"gpu-pwr-totals\" = Consommation par GPU.\n\"gpu-average\" = Usage moyen de tous les GPU.\n\"gpu-vram-total\" = Usage VRAM de tous les GPU.\n\"gpu-pwr-total\" = Consommation de tous les GPU.\nToutes les statistiques ne sont pas prises en charge par tous les périphériques.",
    'options.desc.cpu_invert_lower' => "Bascule l'orientation du graphique CPU inférieur.\n\nTrue ou False.",
    'options.desc.cpu_single_graph' => "Désactiver complètement le graphique CPU inférieur.\n\nN'affiche que le graphique CPU supérieur et\nl'adapte à la hauteur de la boîte.\n\nTrue ou False.",
    'options.desc.show_gpu_info' => "Afficher les infos gpu dans la boîte cpu.\n\nBascule les statistiques gpu dans la boîte cpu et\nle graphique gpu (si \"cpu_graph_lower\" est sur\n\"Auto\").\n\n\"Auto\" pour afficher quand aucune boîte gpu n'est affichée.\n\"On\" pour toujours afficher.\n\"Off\" pour ne jamais afficher.",
    'options.desc.check_temp' => "Activer le relevé de température du cpu.\n\nTrue ou False.",
    'options.desc.cpu_sensor' => "Capteur de température du cpu.\n\nSélectionner le capteur correspondant à la\ntempérature de votre cpu.\n\nMettre à \"Auto\" pour la détection automatique.",
    'options.desc.show_coretemp' => "Afficher les températures des cœurs du cpu.\n\nNe fonctionne que si check_temp est True et\nque le système remonte les températures des cœurs.",
    'options.desc.cpu_core_map' => "Correspondance personnalisée entre cœur et coretemp.\n\nPeut être nécessaire sur certains cpu pour obtenir\nla bonne température pour le bon cœur.\n\nUtiliser lm-sensors ou équivalent pour voir quels\ncœurs remontent des températures sur votre machine.\n\nFormat : \"X:Y\"\nX=cœur avec la mauvaise température.\nY=cœur avec la bonne température.\nUtiliser une espace comme séparateur entre\nplusieurs entrées.\n\nExemple : \"4:0 5:1 6:3\"",
    'options.desc.temp_scale' => "Échelle de température à utiliser.\n\nCelsius, échelle par défaut.\n\nFahrenheit, l'échelle américaine.\n\nKelvin, 0 = zéro absolu, 1 degré de variation\néquivaut à 1 degré de variation en Celsius.\n\nRankine, 0 = zéro absolu, 1 degré de variation\néquivaut à 1 degré de variation en Fahrenheit.",
    'options.desc.show_cpu_freq' => "Afficher la fréquence du CPU.\n\nPeut provoquer des ralentissements sur les systèmes\navec beaucoup de cœurs et certaines versions du noyau.",
    'options.desc.freq_mode' => "Comment la fréquence du CPU sera affichée.\n\nFirst, la fréquence du premier\ncœur.\n\nRange, afficher la fréquence la plus basse et la plus haute.\n\nLowest, la fréquence la plus basse.\n\nHighest, la fréquence la plus haute.\n\nAverage, somme divisée par le nombre de cœurs.",
    'options.desc.show_core_freq' => "Comment la fréquence du CPU par cœur sera affichée.\n\n\"off\" = fréquence par cœur désactivée\n\"value\" = seule la dernière valeur est affichée\n\"graph\" = affichée sous forme de graphique d'historique",
    'options.desc.custom_cpu_name' => "Nom de modèle de cpu personnalisé dans la boîte de pourcentage cpu.\n\nChaîne vide pour désactiver.",
    'options.desc.show_uptime' => "Affiche la durée de fonctionnement du système dans la boîte CPU.\n\nPeut aussi s'afficher dans l'horloge en utilisant\n\"/uptime\" dans le format.\n\nTrue ou False.",
    'options.desc.show_cpu_watts' => "Affiche la consommation électrique du CPU en watts.\n\nNécessite l'accès en lecture aux compteurs\nd'énergie RAPL.\n\nTrue ou False.",
    'options.desc.mem_graphs' => "Afficher des graphiques pour les valeurs de mémoire.\n\nTrue ou False.",
    'options.desc.mem_selected' => "Métriques de mémoire à afficher.\n\n\"default\", \"used\", \"available\", \"cached\",\n\"free\" ou \"swap_used\".\n\n\"default\" affiche toutes les métriques.\nToute autre option force \"Mem graphs\".",
    'options.desc.show_disks' => "Scinder la boîte mémoire pour afficher aussi les disques.\n\nTrue ou False.",
    'options.desc.show_io_stat' => "Basculer les graphiques d'activité d'E/S.\n\nAfficher de petits graphiques d'E/S pour l'activité\ndu disque (temps d'occupation) hors mode E/S.\n\nTrue ou False.",
    'options.desc.io_mode' => "Bascule le mode E/S des disques.\n\nAffiche de grands graphiques des débits de\nlecture/écriture au lieu des jauges de\npourcentage utilisé/libre.\n\nTrue ou False.",
    'options.desc.io_graph_combined' => "Basculer les graphiques de lecture et d'écriture combinés.\n\nN'a d'effet que si \"io mode\" est True.\n\nTrue ou False.",
    'options.desc.io_graph_speeds' => "Définir les débits maximaux des graphiques d'E/S.\n\nDéfinit manuellement quel débit en MiB/s\néquivaut à 100 pour cent dans les graphiques d'E/S.\n(100 MiB/s par défaut).\n\nFormat : \"device:speed\", séparer les disques par\ndes espaces \" \".\n\nExemple : \"/dev/sda:100 /dev/sdb:20\".",
    'options.desc.show_swap' => "Indique si la mémoire swap doit être affichée dans la boîte mémoire.\n\nTrue ou False.",
    'options.desc.show_zswap' => "Indique si l'usage de zswap doit être affiché dans la boîte mémoire.\nAffiche la taille compressée stockée en RAM.\n\nTrue ou False.",
    'options.desc.swap_disk' => "Afficher le swap comme un disque.\n\nIgnore la valeur de show_swap ci-dessus.\nS'insère après le premier disque.",
    'options.desc.only_physical' => "Filtrer les disques non physiques.\n\nMettre à False pour inclure les disques réseau,\nles disques RAM et similaires.\n\nTrue ou False.",
    'options.desc.use_fstab' => "(Linux) Lire la liste des disques depuis /etc/fstab.\n\nCela désactive aussi only_physical.\n\nTrue ou False.",
    'options.desc.zfs_hide_datasets' => "(Linux) Masquer les datasets ZFS dans la liste des disques.\n\nÀ True, tous les datasets sont masqués\net seuls les pools ZFS sont affichés.\n\n(Les statistiques d'E/S seront calculées par pool)\n\nTrue ou False.",
    'options.desc.disk_free_priv' => "(Linux) Type d'espace disque disponible.\n\nMettre à true pour afficher l'espace disque\ndisponible pour les utilisateurs privilégiés.\n\nMettre à false pour afficher celui disponible\npour les utilisateurs normaux.",
    'options.desc.disks_filter' => "Filtre optionnel des disques affichés.\n\nDoit être le chemin complet d'un point de montage.\nSéparer plusieurs valeurs par des\nespaces \" \".\n\nSeuls les disques correspondant au filtre sont affichés.\nPréfixer par exclude= pour n'afficher que les\ndisques ne correspondant pas.\n\nExemples :\n/boot /home/user\nexclude=/boot /home/user",
    'options.desc.disks_order' => "Ordre d'affichage personnalisé optionnel des disques.\n\nChemins complets de points de montage séparés\npar des espaces \" \".\nUtiliser \"swap\" pour positionner l'entrée swap.\n\nLes disques listés sont affichés en premier dans\nl'ordre donné, les autres suivent dans leur\nordre par défaut.\n\nExemples :\n/ swap /home\n/mnt/data /",
    'options.desc.zfs_arc_cached' => "(Linux) Compter l'ARC ZFS comme mémoire en cache.\n\nAjoute l'ARC ZFS utilisé à la mémoire en cache et\nl'ARC ZFS disponible à la mémoire disponible.\nLe noyau Linux les compte sinon\ncomme mémoire utilisée.\n\nTrue ou False.",
    'options.desc.swap_upload_download' => "Échanger les positions des graphiques de débit\nmontant et descendant.\n\nPermet une vue plus « intuitive » avec\nle débit descendant en bas.",
    'options.desc.net_download' => "Valeur fixe du débit descendant des graphiques réseau.\n\nValeur en Mébibits, \"100\" par défaut.\n\nPeut être basculée avec le bouton auto.",
    'options.desc.net_upload' => "Valeur fixe du débit montant des graphiques réseau.\n\nValeur en Mébibits, \"100\" par défaut.\n\nPeut être basculée avec le bouton auto.",
    'options.desc.net_auto' => "Démarrer en mode de remise à l'échelle automatique des graphiques réseau.\n\nIgnore au démarrage les valeurs définies ci-dessus\net descend jusqu'à 10 Kibioctets au minimum.\n\nTrue ou False.",
    'options.desc.net_sync' => "Synchronisation de l'échelle réseau.\n\nSynchronise l'échelle du débit descendant et montant\nsur celle qui est actuellement la plus élevée.\n\nTrue ou False.",
    'options.desc.net_iface' => "Interface réseau.\n\nDéfinit manuellement l'interface réseau de départ.\n\nSinon, la carte réseau avec le plus fort volume\ndescendant total depuis le démarrage est choisie\nautomatiquement.",
    'options.desc.base_10_bitrate' => "Débit en base 10\n\nTrue :  Utiliser les préfixes SI pour les débits\n        (1000Kbps = 1Mbps)\nFalse : Utiliser les préfixes binaires pour les débits\n        (1024Kibps = 1Mibps)\nAuto :  Utiliser le réglage General -> Base 10 Sizes\n        pour les débits\n\nTrue, False ou Auto",
    'options.desc.net_hide_ip' => "Masque l'adresse IP dans la boîte net.\n\nTrue ou False.",
    'options.desc.proc_sorting' => "Option de tri des processus.\n\nValeurs possibles :\n\"pid\", \"name\", \"command\", \"threads\",\n\"user\", \"memory\", \"cpu direct\",\n\"cpu lazy\", \"io read\", \"io write\",\n\"io total\", \"gpu\" et \"gpu memory\".\n\n\"cpu lazy\" met à jour le processus principal dans le temps.\n\"cpu direct\" met à jour le processus principal\ndirectement.",
    'options.desc.proc_reversed' => "Inverser l'ordre de tri des processus.\n\nTrue ou False.",
    'options.desc.proc_tree' => "Vue arbre des processus.\n\nMettre à true pour afficher les processus groupés\npar parents avec des lignes tracées entre\nprocessus parent et enfant.",
    'options.desc.proc_aggregate' => "Agréger les ressources des enfants dans le parent.\n\nDans la vue arbre, inclure toutes les ressources\ndes enfants dans le parent même lorsqu'il est\ndéplié.",
    'options.desc.proc_tree_auto_collapse' => "Replier automatiquement les parents chargés dans la vue arbre.\n\nÀ l'entrée en mode arbre, replier automatiquement\ntout processus ayant au moins ce nombre\nd'enfants directs.\n\nUtile pour masquer les applications multiprocessus\nbruyantes comme Chrome, Firefox ou Electron.\n\nMettre à 0 pour désactiver.\n\nValeur min. : 0\nValeur max. : 10000",
    'options.desc.proc_colors' => "Activer les couleurs dans la vue des processus.\n\nTrue ou False.",
    'options.desc.proc_gradient' => "Activer le dégradé d'estompage de la vue des processus.\n\nS'estompe depuis le haut ou la sélection actuelle.\nLa valeur maximale d'estompage est égale à la\ncouleur \"inactive_fg\" du thème actuel.",
    'options.desc.proc_per_core' => "Usage des processus par cœur.\n\nIndique si l'usage cpu d'un processus est relatif\nau cœur sur lequel il s'exécute ou à la puissance\ncpu totale disponible.\n\nSi true et que le processus est multithread,\nl'usage cpu peut dépasser 100%.",
    'options.desc.proc_mem_bytes' => "Afficher la mémoire en octets dans la liste des processus.\n \nAffichera le pourcentage de la mémoire totale\nsi False.",
    'options.desc.keep_dead_proc_usage' => "Usage cpu et mémoire des processus terminés\n\nMettre à true pour qu'un processus conserve l'usage\ncpu et mémoire qu'il avait à sa mort pendant\nla pause.",
    'options.desc.proc_cpu_graphs' => "Afficher un graphique cpu pour chaque processus.\n\nTrue ou False",
    'options.desc.proc_filter_kernel' => "(Linux) Filtrer les processus du noyau de l'affichage.\n\nMettre à 'True' pour filtrer les processus\ninternes lancés par le noyau Linux.",
    'options.desc.proc_filter_containers' => "(Linux) Masquer les processus dans des conteneurs.\n\nMettre à 'True' pour masquer de la liste des\nprocessus ceux qui s'exécutent dans des\nconteneurs (et des invités KVM).\n\nBasculer avec la touche \"O\" dans la boîte des processus.\n\nLes conteneurs sont détectés par cgroup, ce qui\ncouvre docker, podman, kubernetes, lxc,\nsystemd-nspawn et d'autres runtimes OCI.",
    'options.desc.proc_command_basename' => "Raccourcir les chemins d'exécutables dans les commandes.\n\nN'afficher que le nom de fichier de l'exécutable,\nen conservant tous les arguments de la commande.\n\nS'applique à la liste des processus et à la vue arbre.\nSélectionner un processus et appuyer sur Entrée pour\nvoir sa commande d'origine dans la vue détaillée.\n\nTrue ou False.",
    'options.desc.proc_follow_detailed' => "Suivre le processus sélectionné avec la vue détaillée\n\nSi 'True', à l'ouverture de la vue détaillée, le\nprocessus sera suivi dans la liste. Appuyer à\nnouveau sur entrée fermera la vue détaillée\net cessera de suivre le processus.",
    'options.desc.proc_info_smaps' => "Utiliser /proc/[pid]/smaps pour les informations mémoire\ndans la boîte d'infos du processus.\n\nTrès lent mais plus précis.\n\nTrue ou False.",
    'options.desc.nvml_measure_pcie_speeds' => "Mesurer le débit PCIe sur les cartes NVIDIA.\n\nPeut nuire aux performances de certaines cartes.\n\nTrue ou False.",
    'options.desc.rsmi_measure_pcie_speeds' => "Mesurer le débit PCIe sur les cartes AMD.\n\nPeut nuire aux performances de certaines cartes.\n\nTrue ou False.",
    'options.desc.gpu_mirror_graph' => "Inverser horizontalement le graphique GPU.\n\nTrue ou False.",
    'options.desc.shown_gpus' => "Définit manuellement les fabricants de gpu à afficher.\n\nLes valeurs disponibles sont\n\"nvidia\", \"amd\", \"intel\"\net \"apple\".\nSéparer les valeurs par des espaces.",
    'options.desc.custom_gpu_name0' => "Nom de modèle personnalisé de gpu0 dans la boîte de statistiques gpu.\n\nChaîne vide pour désactiver.",
    'options.desc.custom_gpu_name1' => "Nom de modèle personnalisé de gpu1 dans la boîte de statistiques gpu.\n\nChaîne vide pour désactiver.",
    'options.desc.custom_gpu_name2' => "Nom de modèle personnalisé de gpu2 dans la boîte de statistiques gpu.\n\nChaîne vide pour désactiver.",
    'options.desc.custom_gpu_name3' => "Nom de modèle personnalisé de gpu3 dans la boîte de statistiques gpu.\n\nChaîne vide pour désactiver.",
    'options.desc.custom_gpu_name4' => "Nom de modèle personnalisé de gpu4 dans la boîte de statistiques gpu.\n\nChaîne vide pour désactiver.",
    'options.desc.custom_gpu_name5' => "Nom de modèle personnalisé de gpu5 dans la boîte de statistiques gpu.\n\nChaîne vide pour désactiver.",
    'help.proc_width' => 'Ajuster la largeur de la boîte proc de 1 % (mem ou net affichée).',
    'help.proc_width10' => 'Ajuster la largeur de la boîte proc de 10 % (mem ou net affichée).',
    'help.proc_width_max' => 'Boîte proc à la largeur maximale (minimale avec proc_left).',
    'help.proc_width_min' => 'Boîte proc à la largeur minimale (maximale avec proc_left).',
    'help.proc_width_reset' => 'Réinitialiser le pourcentage de largeur de la boîte proc à 55 %.',
    // ---- tree state (U4 #1791c) ----
    'config.desc.proc_tree_persist_state' => "Conserver d'une exécution à l'autre les choix manuels de dépliage/repliage de l'arbre, selon l'ascendance par nom de processus.\nEnregistré dans \$XDG_STATE_HOME/candy-top/tree-state.json, pas dans ce fichier.",
    'options.desc.proc_tree_persist_state' => "Mémoriser le dépliage manuel de l'arbre.\n\nEnregistrer d'une exécution de candy-top à l'autre\nles choix manuels de dépliage/repliage, selon\nl'ascendance par nom de processus.\n\nLes PID ne sont pas enregistrés car ils changent.\n\nEnregistré dans \$XDG_STATE_HOME/candy-top/\ntree-state.json (sinon ~/.local/state).",
    'state.warn.write_failed' => "Impossible d'enregistrer l'état de l'arbre dans {path} : {reason}",
    'state.warn.pruned' => "État de l'arbre enregistré après abandon de {paths} chemins les moins récemment utilisés pour rester sous {bytes} octets",
    // ---- gpu boxes (U4 #1730/#1881/#985/#1839) ----
    'config.desc.gpu_box_columns' => "Nombre de boîtes GPU à placer côte à côte au lieu de les empiler verticalement.\n\"Auto\" utilise autant de colonnes que la largeur du terminal le permet, ou indiquer un nombre (1-6) pour le forcer.",
    'options.desc.gpu_box_columns' => "Boîtes GPU côte à côte.\n\nNombre de boîtes gpu à placer sur une même ligne\nau lieu de les empiler verticalement.\n\n\"Auto\" utilise autant de colonnes que la largeur\ndu terminal le permet (une boîte fait au moins\n34 colonnes de large).\n\nOu un nombre 1 - 6 pour le forcer.",
    'config.warn.too_many_gpu_boxes' => "Trop de boîtes GPU dans shown_boxes ! Jusqu'à 6 peuvent être affichées à la fois.",
    'config.warn.invalid_gpu_box_columns' => 'Valeur invalide pour gpu_box_columns, doit être "Auto" ou un nombre entre 1 et 6.',
    'config.warn.invalid_gpu_slots' => "Emplacements de panneau gpu invalides : numéros d'emplacement 0-5, chacun au plus une fois.",
    'config.preset.too_many_gpu_boxes' => 'Trop de boîtes GPU saisies pour le preset !',
